def _copy_evidence_list(name: str, value: object) -> list[str]:
    if not isinstance(value, list):
        raise ValueError(f"{name} must be a list of non-empty strings")
    snapshot = list(value)
    if any(not isinstance(item, str) or not item.strip() for item in snapshot):
        raise ValueError(f"{name} must be a list of non-empty strings")
    return snapshot


def build_evidence_card(
    *,
    workflow: str,
    verdict: str,
    verified: list[str],
    snapshot: list[str],
    unverified: list[str],
    blocked: list[str],
    commands: list[dict[str, object]],
    artifacts: list[str],
    restore: str | None,
    next_action: str,
) -> dict[str, object]:
    """Normalize caller-supplied evidence without collecting or inventing it."""

    if verdict not in ("PASS", "FAIL", "BLOCKED"):
        raise ValueError(f"unknown evidence verdict: {verdict}")
    if not isinstance(workflow, str) or re.fullmatch(
        r"[a-z0-9]+(?:-[a-z0-9]+)*", workflow
    ) is None:
        raise ValueError("workflow must be a non-empty kebab-case string")

    normalized_verified = _copy_evidence_list("verified", verified)
    normalized_snapshot = _copy_evidence_list("snapshot", snapshot)
    normalized_unverified = _copy_evidence_list("unverified", unverified)
    normalized_blocked = _copy_evidence_list("blocked", blocked)
    normalized_artifacts = _copy_evidence_list("artifacts", artifacts)

    if not isinstance(commands, list):
        raise ValueError("commands must be a list")
    normalized_commands: list[dict[str, object]] = []
    for command_evidence in commands:
        if not isinstance(command_evidence, Mapping):
            raise ValueError("command evidence must be a mapping")
        if set(command_evidence) != {"command", "exit_code"}:
            raise ValueError("command evidence requires command and exit_code")
        command = command_evidence["command"]
        exit_code = command_evidence["exit_code"]
        if not isinstance(command, str) or not command.strip():
            raise ValueError("command must be a non-empty string")
        if isinstance(exit_code, bool) or not (
            isinstance(exit_code, int) or exit_code is None
        ):
            raise ValueError("exit_code must be an integer or None")
        normalized_commands.append(
            {"command": command, "exit_code": exit_code}
        )

    if restore is not None and not isinstance(restore, str):
        raise ValueError("restore must be a string or None")
    if not isinstance(next_action, str) or not next_action.strip():
        raise ValueError("next_action must be a non-empty string")
    if verdict == "PASS" and not normalized_verified:
        raise ValueError("PASS requires verified evidence")
    if verdict == "PASS" and normalized_blocked:
        raise ValueError("PASS cannot include blockers")
    if verdict == "PASS" and any(
        command_evidence["exit_code"] != 0
        for command_evidence in normalized_commands
    ):
        raise ValueError("PASS requires every command to have exit_code 0")
    if verdict == "BLOCKED" and not normalized_blocked:
        raise ValueError("BLOCKED requires at least one blocker")

    return {
        "schema_version": 1,
        "verdict": verdict,
        "workflow": workflow,
        "verified": normalized_verified,
        "snapshot": normalized_snapshot,
        "unverified": normalized_unverified,
        "blocked": normalized_blocked,
        "commands": normalized_commands,
        "artifacts": normalized_artifacts,
        "restore": restore,
        "next_action": next_action,
    }


